    const s = await resolveSession(req.headers.authorization);
    if (s.kind === "db_down")
      return { ok: false, code: 503, body: { error: "not_ready", reason: "db_down" } };
    if (s.kind === "none") return { ok: false, code: 401, body: { error: "unauthorized" } };
