      if (post.status !== "published") {
        reply.code(410);
        return { error: "gone", reason: "\u5185\u5BB9\u4E0D\u5B58\u5728\u6216\u5DF2\u4E0B\u67B6" };
      }
      const cr = await db2.pool.query(
        "select count(*)::text as n from comments where post_id = $1 and status='published'",
        [id]
      );
